  const turb = Math.sin(sx*0.06+Math.sin(sy*0.04+t)*3+t*0.6)*Math.cos(sy*0.05+Math.sin(sx*0.035-t)*2-t*0.4);
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral*0.4 + cross*0.3 + turb*0.15)*2.0);
  const blend = reaction*0.65 + cell*0.2 + turb*0.15, v = blend*0.5+0.5;
